assert not re.search(r"[–—]", vis) and not re.search(r"ממשק|מערכת|פלטפורמה|סימולצי|בקרוב", vis), "language DNA"
print("[page %d] H1, answer, seller section, %d FAQ added | title %d chars | desc %d chars" % (PID, len(QA), len(TITLE), len(DESC)))
if DRY:
    sys.exit(0)
bk = os.path.join(H, "page-backup"); os.makedirs(bk, exist_ok=True)
io.open(os.path.join(bk, "page-%d-%s.html" % (PID, time.strftime("%Y%m%d-%H%M%S"))), "w", encoding="utf-8", newline="").write(raw)
io.open(os.path.join(bk, "page-%d-meta-%s.txt" % (PID, time.strftime("%Y%m%d-%H%M%S"))), "w", encoding="utf-8").write(repr(r["meta"]))
req("POST", "/wp-json/wp/v2/pages/%d" % PID, {"content": new, "meta": {"_yoast_wpseo_title": TITLE, "_yoast_wpseo_metadesc": DESC, "_yoast_wpseo_bctitle": CRUMB}})
back = req("GET", "/wp-json/wp/v2/pages/%d?context=edit&_fields=content" % PID)[1]["content"]["raw"]
time.sleep(3)
page = urllib.request.urlopen(urllib.request.Request(r["link"] + "?x=%d" % time.time(), headers={"User-Agent": "Mozilla/5.0"}), timeout=90).read().decode("utf-8", "replace")
bd = page[page.find("<body"):]
title = re.search(r"<title>(.*?)</title>", page, re.S).group(1)
ok = {"read-back": back == new, "one h1": bd.count("<h1") == 1, "new H1": "הערכת שווי דירה: כמה שווה הדירה שלכם" in bd, "title": title.strip() == TITLE,
      "seller section": "איך יודעים מה מחיר השיווק הנכון לדירה?" in bd, "FAQPage questions >= 22": page.count('"@type":"Question"') >= 22,
      "tool still mounted": 'data-nli="pval"' in bd}
for k, v in ok.items(): print("   ", "OK " if v else "BAD", k)
print("    questions in schema:", page.count('"@type":"Question"'))
